/* 아이템 이미지 파일 번호 조회 */
SELECT ATCH_FILE_SN
  FROM ITEM
 WHERE ITEM_SN = #{itemSn}

/* 상점 아이템 목록 조회(부위 필터) */ SELECT WHERE I.NTSL_YN = 'Y'
AND I.ITEM_REGN_CD = #{itemRegnCd}
ORDER BY I.ITEM_REGN_CD , I.SORT_SEQ , I.ITEM_SN

